mapper.select:
/* AppTbm01Mapper.selectMyAttendance */
SELECT
      ATTENDANCE_CD          AS attendanceCd
    , SESSION_CD             AS sessionCd
    , ENTRY_AT               AS entryAt
    , ENTRY_DISTANCE_M       AS entryDistanceM
    , EXIT_AT                AS exitAt
    , EXIT_TYPE_CD           AS exitTypeCd
    , COMPLETION_STATUS_CD   AS completionStatusCd
FROM TB_TBM_ATTENDANCE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'

mapper.insert:
/* AppTbm01Mapper.insertAttendance */
INSERT INTO TB_TBM_ATTENDANCE (
      ATTENDANCE_CD
    , CMPNY_CD
    , SESSION_CD
    , USER_TYPE_CD
    , USER_CD
    , ENTRY_TYPE_CD
    , ENTRY_AT
    , ENTRY_GPS_LAT
    , ENTRY_GPS_LON
    , ENTRY_DISTANCE_M
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      CONCAT('A', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'TBM_ATTENDANCE_CD'))
    , #{cmpnyCd}
    , #{sessionCd}
    , #{userTypeCd}
    , #{userCd}
    , #{entryTypeCd}
    , NOW()
    , #{lat}
    , #{lon}
    , #{distanceM}
    , 'N'
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.update:
/* AppTbm01Mapper.updateExit */
UPDATE TB_TBM_ATTENDANCE
SET
      EXIT_TYPE_CD           = #{exitTypeCd}
    , EXIT_AT                = NOW()
    , EXIT_SIGN_FILE_MGMT_CD = #{exitSignFileMgmtCd}
    , COMPLETION_STATUS_CD   = #{completionStatusCd}
    /* prafta-051-08: 앱 포그라운드 누적초(nullable). null 이면 그대로 NULL 저장. */
    , APP_FOREGROUND_SEC     = #{appForegroundSec}
    , STATUS_UPDATED_BY      = #{updateNo}
    , STATUS_UPDATED_AT      = NOW()
    , UPDATE_NO              = #{updateNo}
    , UPDATE_DATE            = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'
  AND EXIT_AT IS NULL

mapper.select:
/* AppTbm01Mapper.selectSessionState */
SELECT
      S.STATUS_CD                                       AS statusCd
    , DATE_FORMAT(S.STARTED_AT, '%Y-%m-%d %H:%i')       AS startedAt
    , DATE_FORMAT(S.ENDED_AT, '%Y-%m-%d %H:%i')         AS endedAt
    , ST.SYNC_STATE_CD                                  AS syncStateCd
FROM TB_TBM_SESSION S
     LEFT OUTER JOIN TB_TBM_SESSION_STATE ST
        ON (
            S.CMPNY_CD = ST.CMPNY_CD
        AND S.SESSION_CD = ST.SESSION_CD
        )
WHERE S.CMPNY_CD = #{cmpnyCd}
  AND S.SITE_CD = #{siteCd}
  AND S.SESSION_CD = #{sessionCd}
  AND S.DEL_YN = 'N'

/* AppTbm01Mapper.selectSessionContentBody */
SELECT
    S.CONTENT_BODY
FROM TB_TBM_SESSION S
WHERE S.CMPNY_CD = #{cmpnyCd}
  AND S.SITE_CD = #{siteCd}
  AND S.SESSION_CD = #{sessionCd}
  AND S.DEL_YN = 'N'

/* AppTbm01Mapper.selectSessionContentItems */ SELECT I.MTRL_CD AS mtrlCd , I.MTRL_ITEM_CD AS mtrlItemCd , I.MTRL_ITEM_TYPE AS itemType , I.FILE_MGMT_CD AS fileMgmtCd , I.URL AS url , I.MTRL_DESC AS itemDesc , I.SORT_IDX AS sortIdx
, F.FILE_PATH AS filePath , F.FILE_EXT AS fileExt FROM TB_TBM_EDU_MTRL_ITEM I INNER JOIN TB_TBM_SESSION_CONTENT SC ON ( I.MTRL_CD = SC.MTRL_CD ) LEFT OUTER JOIN TB_FILE_INFO F ON ( F.CMPNY_CD = SC.CMPNY_CD AND F.FILE_MGMT_CD = I.FILE_MGMT_CD ) WHERE SC.CMPNY_CD = #{cmpnyCd} AND SC.SESSION_CD = #{sessionCd} AND I.USE_YN = 'Y'
AND EXISTS ( SELECT 1 FROM TB_TBM_EDU_MTRL M WHERE M.MTRL_CD = I.MTRL_CD AND M.CMPNY_CD = #{cmpnyCd} ) AND EXISTS ( SELECT 1 FROM TB_TBM_SESSION S WHERE S.CMPNY_CD = SC.CMPNY_CD AND S.SESSION_CD = SC.SESSION_CD AND S.SITE_CD = #{siteCd} AND S.DEL_YN = 'N' ) ORDER BY SC.DISPLAY_ORDER, I.SORT_IDX

/* AppTbm01Mapper.selectSessionMaterialTitles */
SELECT
    M.TITLE
FROM TB_TBM_SESSION_CONTENT SC
     INNER JOIN TB_TBM_EDU_MTRL M
        ON (
            SC.MTRL_CD = M.MTRL_CD
        AND SC.CMPNY_CD = M.CMPNY_CD
        )
WHERE SC.CMPNY_CD = #{cmpnyCd}
  AND SC.SESSION_CD = #{sessionCd}
  AND EXISTS (
        SELECT 1
        FROM TB_TBM_SESSION S
        WHERE S.CMPNY_CD = SC.CMPNY_CD
          AND S.SESSION_CD = SC.SESSION_CD
          AND S.SITE_CD = #{siteCd}
          AND S.DEL_YN = 'N'
      )
ORDER BY SC.DISPLAY_ORDER

