/* AppTbm01Mapper.updateWithdraw */
UPDATE TB_TBM_ATTENDANCE
SET
      EXIT_TYPE_CD         = #{exitTypeCd}
    , EXIT_AT              = NOW()
    , COMPLETION_STATUS_CD = #{completionStatusCd}
    , STATUS_UPDATED_BY    = #{updateNo}
    , STATUS_UPDATED_AT    = NOW()
    , UPDATE_NO            = #{updateNo}
    , UPDATE_DATE          = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'
  AND EXIT_AT IS NULL

mapper.select:
/* AppTbm01Mapper.selectInProgressAttendanceSessionCds */
SELECT
    AT.SESSION_CD
FROM TB_TBM_ATTENDANCE AT
WHERE AT.CMPNY_CD = #{cmpnyCd}
  AND AT.USER_TYPE_CD = #{userTypeCd}
  AND AT.USER_CD = #{userCd}
  AND AT.DEL_YN = 'N'
  AND AT.ENTRY_AT IS NOT NULL
  AND AT.EXIT_AT IS NULL
  AND EXISTS (
        SELECT 1
        FROM TB_TBM_SESSION S
        WHERE S.CMPNY_CD = AT.CMPNY_CD
          AND S.SESSION_CD = AT.SESSION_CD
          AND S.SITE_CD = #{siteCd}
          AND S.DEL_YN = 'N'
      )
ORDER BY AT.SESSION_CD
